const seeds = [
  'Best TMS for small trucking companies',
  'Broker dispatch workflow',
  'EDI 204 explained',
  'How freight brokers automate dispatch'
];
const system = 'You are a freight-tech content strategist for Techvia TMS, a transportation management system for small-to-medium US freight brokers and carriers. You produce commercial, buyer-intent blog topics: the exact questions a broker, dispatcher, or carrier types into Google when they have a problem a TMS solves.';
const user = "Generate 5 buyer-intent blog topics for freight brokers and carriers that naturally lead the reader toward adopting a TMS. Use long-tail commercial angles (best X for Y, X vs Y, cost of, how to, checklist, '... explained'). Prioritise variations of these seed topics, then expand with fresh siblings: " + JSON.stringify(seeds) + ". Return ONLY a JSON array: [{\"title\":\"...\",\"angle\":\"one-sentence hook\"}]. No prose, no markdown fences.";
return [{ json: { system, user, seeds } }];

const raw = $json.choices[0].message.content;
const arr = JSON.parse(raw.replace(/```json\n?|```/g, '').trim());
const stop = new Set(['the','a','an','for','to','of','in','on','and','or','how','what','is','are','your','with','vs','from']);
function slugify(t) {
  return (t || '').toLowerCase().replace(/[^a-z0-9\s-]/g, '').split(/\s+/).filter(w => w && !stop.has(w)).join('-').replace(/-+/g, '-').replace(/^-|-$/g, '');
}
const candidates = arr.slice(0, 5).map(c => ({ title: c.title, angle: c.angle, slug: slugify(c.title) })).filter(c => c.slug);
return [{ json: { candidates } }];

const candidates = $json.candidates || [];
const fresh = candidates.slice(0, 3);
const topicsText = fresh.map((t, i) => `${i + 1}. <b>${t.title}</b>\n   ${t.angle}`).join('\n\n');
return [{ json: { fresh, hasFresh: fresh.length > 0, topicsText } }];

