const staticData = $getWorkflowStaticData('global');
const messageId = $('Send Approval Message').item.json.result.message_id;
staticData[`resume_${messageId}`] = $execution.resumeUrl;
return $input.all();

const idx = Number.isInteger($json.topicNum) ? $json.topicNum : 0;
const fresh = $('Pick Top Topics').first().json.fresh || [];
const t = fresh[idx] || fresh[0];
if (!t) { throw new Error('No topic to resolve for index ' + idx); }
const writerSystem = 'You are a senior freight operations writer for Techvia (techvia.software). Techvia TMS is a transportation management system for small-to-medium US freight brokers and carriers: drag-and-drop dispatch board, fleet and drivers, live GPS tracking, customer invoicing, driver and carrier settlements, and EDI load tenders. Write a complete, SEO-optimised Hugo blog post in markdown for brokers, dispatchers, and carriers. Voice: human and practical. Vary sentence length; use first-person team voice ("we built Techvia TMS because...", "the dispatchers we talk to..."); use concrete freight detail (stops, RateCons, PODs, deadhead, detention). 900-1200 words. Use ## and ### headings and at most one bulleted list. NEVER use these phrases: "in todays fast-paced world", "delve", "moreover", "furthermore", "in conclusion", "unlock the power", "ever-evolving", "landscape", "navigating the". Weave Techvia TMS in once where it genuinely answers the problem, and end with a natural call-to-action paragraph linking to https://www.techvia.software/products/tms . Do not stuff the product everywhere. Output ONLY the markdown body (no frontmatter).';
const writerUser = 'Write the post. Topic: ' + t.title + '. Angle: ' + t.angle + '.';
return [{ json: { topic_title: t.title, topic_angle: t.angle, topic_slug: t.slug, writerSystem, writerUser } }];

const today = new Date().toISOString().split('T')[0];
const body = $('Write Article').item.json.choices[0].message.content;
const metaRaw = $json.choices[0].message.content;
const meta = JSON.parse(metaRaw.replace(/```json\n?|```/g, '').trim());
const title = $('Resolve Topic').item.json.topic_title;
const slug = $('Resolve Topic').item.json.topic_slug;
const angle = $('Resolve Topic').item.json.topic_angle;
const desc = (meta.seo_description || '').substring(0, 150);
const tags = Array.isArray(meta.tags) ? meta.tags : [];
const category = meta.category || 'TMS';
const filename = `${today}-${slug}.md`;
const post_path = `content/posts/${filename}`;
const fm = `---\ntitle: "${title.replace(/"/g, '\\"')}"\ndate: ${today}\ndraft: false\ntags: ${JSON.stringify(tags)}\ncategories: ["${category}"]\ndescription: "${desc.replace(/"/g, '\\"')}"\nshowToc: true\n---\n\n`;
return [{ json: { filename, markdown: fm + body, slug, title, post_path } }];
